class Trip(BaseModel):
    actualDurationInMinutes: int | None = Field(
        None,
        description='Actual duration of this trip in minutes, or the planned duration if no realtime information about this trip is available.',
    )
    bookingUrl: Link | None = None
    crowdForecast: CrowdForecast | None = None
    ctxRecon: str = Field(
        ...,
        description='Reconstruction context for this trip. Can be used to reconstruct this exact trip with the v3/trips/trip endpoint',
    )
    eco: Eco | None = None
    fareLegs: list[FareLeg] | None = None
    fareOptions: TripFareOptions | None = None
    fareRoute: FareRoute | None = None
    fares: list[TripSalesFare] | None = None
    labelListItems: list[LabelListItem] | None = None
    legs: list[Leg]
    messages: list[Message] | None = Field(
        None,
        description='List of messages regarding maintenance or disruption that influences this trip.',
    )
    modalityListItems: list[ModalityListItem] | None = None
    nsiLink: NsiLink | None = None
    optimal: bool = Field(
        ...,
        description='Whether or not this trip is regarded the best possible option of all returned trips',
    )
    overviewPolyLine: list[Coordinate] | None = None
    plannedDurationInMinutes: int | None = Field(
        None, description='Planned duration of this trip in minutes'
    )
    primaryMessage: PrimaryMessage | None = None
    productFare: TripTravelFare | None = None
    punctuality: float | None = None
    realtime: bool
    registerJourney: JourneyRegistrationParameters | None = None
    routeId: str | None = None
    shareUrl: Link | None = None
    sourceCtxRecon: str | None = Field(
        None,
        description="Reconstruction context for this trip set by the travel advice source system. Can be used to interact follow-up requests with the source system, like booking a trip with travel assistance (NSRA). Can be null if the source doesn't provide a ctxRecon",
    )
    status: Status2 = Field(..., description='Status of this trip')
    transfers: int = Field(..., description='Number of public transit transfers')
    travelAssistanceInfo: TravelAssistanceInfo | None = None
    type: Type11
    uid: str = Field(..., description='Unique identifier for this trip')


