class TravelAdvice(BaseModel):
    message: str | None = Field(
        None, description='Optional message indicating why the list of trips is empty.'
    )
    scrollRequestBackwardContext: str | None = Field(
        None,
        description='Scroll context to use when scrolling back in time. Can be used in scrollContext query parameter',
    )
    scrollRequestForwardContext: str | None = Field(
        None,
        description='Scroll context to use when scrolling forward in time. Can be used in scrollContext query parameter',
    )
    source: Source = Field(
        ..., description='Source system that has generated these travel advices'
    )
    travelAdviceMessage: TravelAdviceMessage | None = None
    trips: list[Trip] = Field(..., description='List of trips')


class ApiV3TripsGetResponse(RootModel[list[TravelAdvice]]):
    root: list[TravelAdvice]
